{"implementation": "def solve(case):
    if 'tokens' not in case or 'calls' not in case:
        raise ValueError("Missing required fields: tokens, calls")
    tokens = case['tokens']
    calls = case['calls']
    # Validate each call has required fields
    for c in calls:
        for key in ('call_id', 'start', 'end', 'score', 'replacement_tokens'):
            if key not in c:
                raise ValueError(f"Call missing field: {key}")
    # Sort candidates: descending score, ascending start, ascending call_id
    sorted_calls = sorted(calls, key=lambda c: (-c['score'], c['start'], c['call_id']))
    selected = []
    for c in sorted_calls:
        overlap = False
        for s in selected:
            if not (c['end'] <= s['start'] or c['start'] >= s['end']):
                overlap = True
                break
        if not overlap:
            selected.append(c)
    # Order selected by start for reporting
    selected_sorted = sorted(selected, key=lambda c: c['start'])
    selected_ids = [c['call_id'] for c in selected_sorted]
    # Apply replacements from right to left to preserve offsets
    result_tokens = tokens[:]
    for c in sorted(selected, key=lambda c: -c['start']):
        result_tokens = result_tokens[:c['start']] + c['replacement_tokens'] + result_tokens[c['end']:]
    return {
        "selected_call_ids": selected_ids,
        "tokens": result_tokens
    }"}
